#!/usr/bin/env python3
"""Register source packages and query the dependency graph generated by L4Re."""
import os
import sys
from collections import defaultdict
from pathlib import Path


def register_packages(root):
    registry = root / "l4mk/pkg"
    packages = {"l4re-core": root / "l4re"}
    for pkg in (root / "pkg").iterdir():
        if (pkg / "Control").is_file() or any(pkg.glob("*/Control")):
            packages[pkg.name] = pkg
    for link in registry.iterdir():
        if link.is_symlink() and not link.exists():
            link.unlink(missing_ok=True)
    for name, source in packages.items():
        link = registry / name
        try:
            link.symlink_to(os.path.relpath(source, registry))
        except FileExistsError:
            if link.resolve() != source.resolve():
                raise ValueError(f"{link} already points to a different package")


def built_consumers(tree, changed):
    graph = tree / ".Package.deps"
    if not graph.exists():
        return []
    consumers = defaultdict(set)
    for line in graph.read_text().splitlines():
        target, _, deps = line.partition(": ")
        if target.startswith("pkg/") and " " not in target:
            for dep in deps.split():
                consumers[dep].add(target)
    seen = {changed}
    pending = [changed]
    while pending:
        for target in consumers[pending.pop()] - seen:
            pending.append(target)
            seen.add(target)
    return sorted(pkg for pkg in seen - {changed}
                  if (tree / pkg).is_dir() and any((tree / pkg).rglob("OBJ-*")))


if __name__ == "__main__":
    if sys.argv[1] == "register":
        register_packages(Path(sys.argv[2]))
    else:
        print(*built_consumers(Path(sys.argv[2]), sys.argv[3]), sep="\n")
